			if w[0] == '0':
				same_0.append(w)
			elif w[0] == '1':
				same_1.append(w)
		elif w[0] == '0' and w[-1] == '1':
			zero_1.append(w)
			index_zero_1.append(index)
		elif w[0] == '1' and w[-1] == '0':
			one_0.append(w)
			index_one_0.append(index)
	if len(same_1) > 0 and len(same_0) == 0 and (len(zero_1) == 0) and (len(one_0) == 0):
		print(0)
		continue
	elif len(same_0) > 0 and len(same_1) == 0 and (len(zero_1) == 0) and (len(one_0) == 0):
		print(0)
		continue
	elif len(same_0) > 0 and len(same_1) > 0 and (len(zero_1) == 0) and (len(one_0) == 0):
		print(-1)
		continue
