			words_to_reverse = zero_1
			words_set = set(one_0)
			index_map = index_zero_1
			required = (len(zero_1) - len(one_0)) // 2
		elif len(one_0) > len(zero_1):
			words_to_reverse = one_0
			words_set = set(zero_1)
			index_map = index_one_0
			required = (len(one_0) - len(zero_1)) // 2
		indices = []
